import{_ as a,o,c as e,a2 as l}from"./chunks/framework.D66Xq0Kv.js";const u=JSON.parse('{"title":"从 Matlab 到 AI Agent：我的转行技术路线复盘","description":"","frontmatter":{"title":"从 Matlab 到 AI Agent：我的转行技术路线复盘","date":"2026-09-29T00:00:00.000Z","tags":["转行","学习路径","职业成长"]},"headers":[],"relativePath":"posts/career-pivot.md","filePath":"posts/career-pivot.md","lastUpdated":1790688655000}'),r={name:"posts/career-pivot.md"};function n(i,t,s,h,p,g){return o(),e("div",null,[...t[0]||(t[0]=[l('<h1 id="从-matlab-到-ai-agent-我的转行技术路线复盘" tabindex="-1">从 Matlab 到 AI Agent：我的转行技术路线复盘 <a class="header-anchor" href="#从-matlab-到-ai-agent-我的转行技术路线复盘" aria-label="Permalink to &quot;从 Matlab 到 AI Agent：我的转行技术路线复盘&quot;">​</a></h1><p>我大学读的是数据科学与大数据技术（Python 为主），毕业后第一份工作却做了三年 Matlab——工业智能化软件项目经理，写 PID / GPC 控制算法。离职后转向 Python + AI，做了帧间和两个工程化项目。这条路值得复盘一遍，也许对同样在转型的人有参考。</p><h2 id="第一站-大学-python-打底" tabindex="-1">第一站：大学，Python 打底 <a class="header-anchor" href="#第一站-大学-python-打底" aria-label="Permalink to &quot;第一站：大学，Python 打底&quot;">​</a></h2><p>专业课程以 Python 为主：数据分析、爬虫、机器学习入门。这三年给我的是<strong>数据思维</strong>——处理数据、清洗数据、从数据里找规律。毕业时我以为会去做数据分析，结果去了工业。</p><h2 id="第二站-三年-matlab-工业智能化" tabindex="-1">第二站：三年 Matlab，工业智能化 <a class="header-anchor" href="#第二站-三年-matlab-工业智能化" aria-label="Permalink to &quot;第二站：三年 Matlab，工业智能化&quot;">​</a></h2><p>江苏庞景节能，工业智能化软件项目经理（2022.08 - 2025.10）。</p><ul><li>用 Matlab / Simulink 开发定制化工业程序与生产数据模型</li><li>PID / GPC 控制算法、OPC UA / DA 协议对接现场数据</li><li>联合中科大、南京工大做实验室技术到工业应用的转化</li></ul><p>这三年教会我三件学校教不会的事：<strong>对接真实系统的脏数据、跟现场打交道、把算法变成能上线的东西</strong>。但我也清楚地看到：工业项目周期长、技术栈封闭，我想要的 AI 应用开发不在这里。</p><h2 id="转折-离职后系统性补课" tabindex="-1">转折：离职后系统性补课 <a class="header-anchor" href="#转折-离职后系统性补课" aria-label="Permalink to &quot;转折：离职后系统性补课&quot;">​</a></h2><p>离职不是裸奔，是有计划的补课：</p><ol><li><strong>Python 主线回归</strong>：把大学的知识重拾起来，以 FastAPI 为主线做项目（爬虫、数据库、Web API）</li><li><strong>Java 补后端基础</strong>：自学 Spring / SpringMVC / MyBatis（仓库里还留着 SSM 练习），理解企业级后端的长什么样</li><li><strong>前端入门</strong>：HTML / CSS / JavaScript，为了能独立做出完整产品（帧间就是全栈）</li><li><strong>AI / Agent</strong>：大模型 API 集成、提示词工程、Agent 应用开发——这是主攻方向</li></ol><h2 id="现在-帧间-两个工程化项目" tabindex="-1">现在：帧间 + 两个工程化项目 <a class="header-anchor" href="#现在-帧间-两个工程化项目" aria-label="Permalink to &quot;现在：帧间 + 两个工程化项目&quot;">​</a></h2><ul><li><strong>帧间</strong>：爆款视频拆解与创作系统，从产品定义到全栈开发一人完成（React + FastAPI + PostgreSQL + DeepSeek + Ollama）</li><li><strong>douyin_tool / promotion_agent</strong>：面试题工程化——SQLite、并行、upsert、幂等、Docker、CI、评测，全绿测试</li></ul><h2 id="复盘-转行做对了什么" tabindex="-1">复盘：转行做对了什么 <a class="header-anchor" href="#复盘-转行做对了什么" aria-label="Permalink to &quot;复盘：转行做对了什么&quot;">​</a></h2><ul><li><strong>用作品代替空转</strong>：不纠结&quot;学完再投&quot;，边做项目边学，项目本身就是简历</li><li><strong>旧经验不浪费</strong>：Matlab 的仿真/数据建模思维直接复用到帧间的数据管线设计</li><li><strong>每步都可讲述</strong>：转行故事里的每一步都有仓库、有文章、有代码作证——面试官看到的不是一个&quot;想转行的人&quot;，而是一个&quot;已经转了的人&quot;</li></ul><blockquote><p>面试可展开：为什么从 Matlab 转 Python/AI？——答：工业项目让我学会真实系统怎么工作，但 AI 应用开发的迭代速度和影响力是封闭技术栈给不了的；转行不是抛弃过去，是把数据建模的经验迁移到新的技术栈。</p></blockquote>',16)])])}const d=a(r,[["render",n]]);export{u as __pageData,d as default};
